import requests
from identity_client import FIREBASE_WEB_API_KEY
from identity_models import login_request

FIREBASE_AUTH_REST_API_URL = "https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=" + FIREBASE_WEB_API_KEY

def email_password_login(email, password):
    """
    Signs in a user with email and password using Firebase Authentication REST API
    and returns authentication tokens.
    """
    payload = login_request(email, password)
    try:
        response = requests.post(FIREBASE_AUTH_REST_API_URL, json=payload)
        response.raise_for_status()  # Raise an exception for HTTP errors
        return response.json()
    except requests.exceptions.RequestException as e:
        return {"error": str(e), "message": "Failed to sign in."}

import requests
from identity_client import FIREBASE_WEB_API_KEY
from identity_models import refresh_token_request

FIREBASE_REFRESH_TOKEN_API_URL = "https://securetoken.googleapis.com/v1/token?key=" + FIREBASE_WEB_API_KEY

def refresh_session(refresh_token):
    """
    Refreshes an expired session or access token using the Firebase Authentication REST API.
    """
    payload = refresh_token_request(refresh_token)
    try:
        response = requests.post(FIREBASE_REFRESH_TOKEN_API_URL, json=payload)
        response.raise_for_status()  # Raise an exception for HTTP errors
        return response.json()
    except requests.exceptions.RequestException as e:
        return {"error": str(e), "message": "Failed to refresh token."}

import os
from google.cloud import translate_v3 as translate

PROJECT_ID = os.getenv("GCP_PROJECT_ID", "your-gcp-project-id")

def welcome_translate(text, target_language_code):
    """
    Translates onboarding copy into the user's locale using Google Cloud Translation API.
    """
    client = translate.TranslationServiceClient()
    location = "global"  # Or a specific region, e.g., "us-central1"

    parent = f"projects/{PROJECT_ID}/locations/{location}"

    try:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "target_language_code": target_language_code,
            }
        )
        translations = []
        for translation in response.translations:
            translations.append(translation.translated_text)
        return {"translated_text": translations[0], "target_language": target_language_code}
    except Exception as e:
        return {"error": str(e), "message": "Failed to translate text."}

import os
from google.cloud import firestore

# Initialize Firestore client
db = firestore.Client(project=os.getenv("GCP_PROJECT_ID", "your-gcp-project-id"))

def profile_note_store(user_id, notes_data):
    """
    Persists onboarding notes and support metadata in Google Cloud Firestore.
    `user_id` is the ID of the user these notes pertain to.
    `notes_data` is a dictionary containing the notes and metadata to store.
    """
    try:
        doc_ref = db.collection('onboarding_notes').document(user_id)
        doc_ref.set(notes_data, merge=True) # merge=True allows updating existing fields without overwriting the whole document
        return {"user_id": user_id, "message": "Onboarding notes stored successfully."}
    except Exception as e:
        return {"error": str(e), "message": "Failed to store onboarding notes."}
